/**
 * Module: hooks/useThirdPartyNotices
 *
 * Loads the third-party component inventory and its licence texts for the Licences group of the Policies page.
 *
 * Responsibilities:
 * - `useThirdPartyNotices`: the inventory (`/licences/third-party-notices.json`).
 * - `useLicenceTexts`: the licence texts (`/licences/third-party-texts.json`, about 1.4 MB), read only when a text is
 *   first asked for.
 *
 * Design decisions: both files are static assets generated by `scripts/generate_third_party_notices.py` and served by
 * the front-end container beside the application, so no sign-in or API call is involved and a signed-out visitor can
 * read them. They are fetched with a plain same-origin `fetch` (never the API client, which adds the API origin and the
 * session). Nothing is cached outside the component: the web server revalidates the files, so a repeat visit costs a
 * conditional request rather than a download.
 */
import { useEffect, useState } from "react";

/** One library (an npm or Python package) the product ships. */
export interface LicencePackage {
  ecosystem: "npm" | "python";
  name: string;
  version: string;
  /** Ids of the images or bundles that contain it (see `ThirdPartyNotices.components`). */
  components: string[];
  direct: boolean;
  /** The SPDX expression of the licence. */
  licence: string;
  licence_source: "metadata" | "override" | "classifier" | "package.json";
  /** `notice` when the licence asks for its notice to be kept with the component (file-level or library copyleft). */
  review: "none" | "notice";
  /** Ids into the licence texts file. */
  texts: string[];
  link: string;
}

/** A program or library the image gets from the operating system (not a Python or npm package). */
export interface LicenceSystemComponent {
  name: string;
  licence: string;
  images: string[];
  role: string;
  reason: string;
  source: string;
  use: "program" | "separate-program" | "library" | "build-tool";
  packages: string[];
}

export interface LicenceBaseImage {
  licence: string;
  images: string[];
  note: string;
}

export interface LicenceFont {
  name: string;
  licence: string;
  where: string;
  files: string;
  note: string;
  texts: string[];
}

export interface ThirdPartyNotices {
  schema: number;
  components: { id: string; title: string }[];
  packages: LicencePackage[];
  system_components: LicenceSystemComponent[];
  base_images: Record<string, LicenceBaseImage>;
  fonts: LicenceFont[];
  /** Why each library-copyleft package is allowed, keyed `ecosystem:name`. */
  library_copyleft_reasons: Record<string, string>;
  notes: string[];
}

const NOTICES_URL = "/licences/third-party-notices.json";
const TEXTS_URL = "/licences/third-party-texts.json";

/** The state of one static read. */
export interface StaticRead<T> {
  data: T | null;
  failed: boolean;
}

/**
 * Reads one JSON asset when `enabled` becomes true.
 *
 * @param url The same-origin path of the asset.
 * @param enabled False defers the read (the texts are not needed until a text is opened).
 * @returns The parsed data, or `failed` when the read or the parse failed.
 */
function useStaticJson<T>(url: string, enabled: boolean): StaticRead<T> {
  const [state, setState] = useState<StaticRead<T>>({ data: null, failed: false });
  useEffect(() => {
    if (!enabled) return undefined;
    let cancelled = false;
    fetch(url, { headers: { Accept: "application/json" } })
      .then((response) => {
        if (!response.ok) throw new Error(`${url}: ${response.status}`);
        return response.json() as Promise<T>;
      })
      .then(
        (data) => { if (!cancelled) setState({ data, failed: false }); },
        () => { if (!cancelled) setState({ data: null, failed: true }); },
      );
    return () => { cancelled = true; };
  }, [url, enabled]);
  return state;
}

/** @returns The inventory of shipped components, or `failed` when it could not be read. */
export function useThirdPartyNotices(): StaticRead<ThirdPartyNotices> {
  return useStaticJson<ThirdPartyNotices>(NOTICES_URL, true);
}

/**
 * @param enabled True once a licence text is wanted; the file is not read before.
 * @returns The licence texts keyed by the ids the inventory lists.
 */
export function useLicenceTexts(enabled: boolean): StaticRead<Record<string, string>> {
  return useStaticJson<Record<string, string>>(TEXTS_URL, enabled);
}
